import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:intl/intl.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../providers/announcement_providers.dart';\nimport 'announcement_details_screen.dart';\n\nclass AnnouncementsTab extends ConsumerWidget {\n  const AnnouncementsTab({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final localStorage = ref.watch(localStorageServiceProvider);\n    final schoolId = localStorage.getSchoolCode();\n\n    if (schoolId == null) {\n      return const Center(child: Text('خطأ: كود المدرسة مفقود'));\n    }\n\n    final announcementsAsync = ref.watch(announcementsProvider(schoolId));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('لوحة التبليغات'),\n        centerTitle: true,\n      ),\n      body: announcementsAsync.when(\n        data: (announcements) {\n          if (announcements.isEmpty) {\n            return const Center(child: Text('لا توجد إعلانات حالياً.'));\n          }\n          return ListView.builder(\n            padding: const EdgeInsets.all(16),\n            itemCount: announcements.length,\n            itemBuilder: (context, index) {\n              final ann = announcements[index];\n              final formatter = DateFormat('yyyy-MM-dd');\n              return Card(\n                elevation: 2,\n                margin: const EdgeInsets.only(bottom: 12),\n                shape: RoundedRectangleBorder(\n                  side: ann.priority \n                      ? const BorderSide(color: Colors.redAccent, width: 2) \n                      : BorderSide.none,\n                  borderRadius: BorderRadius.circular(12),\n                ),\n                child: ListTile(\n                  contentPadding: const EdgeInsets.all(16),\n                  title: Row(\n                    mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                    children: [\n                      Expanded(\n                        child: Text(\n                          ann.title, \n                          style: TextStyle(\n                            fontSize: 18, \n                            fontWeight: FontWeight.bold,\n                            color: ann.priority ? Colors.red.shade700 : Colors.black,\n                          ),\n                        ),\n                      ),\n                      if (ann.priority)\n                        const Icon(Icons.warning_amber_rounded, color: Colors.red),\n                    ],\n                  ),\n                  subtitle: Padding(\n                    padding: const EdgeInsets.only(top: 8.0),\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\n                          ann.content,\n                          maxLines: 2,\n                          overflow: TextOverflow.ellipsis,\n                        ),\n                        const SizedBox(height: 8),\n                        Text(\n                          formatter.format(ann.createdAt),\n                          style: const TextStyle(fontSize: 12, color: Colors.grey),\n                        ),\n                      ],\n                    ),\n                  ),\n                  onTap: () {\n                    Navigator.push(\n                      context,\n                      MaterialPageRoute(\n                        builder: (_) => AnnouncementDetailsScreen(announcement: ann),\n                      ),\n                    );\n                  },\n                ),\n              );\n            },\n          );\n        },\n        loading: () => const Center(child: CircularProgressIndicator()),\n        error: (err, stack) => Center(child: Text('خطأ: $err')),\n      ),\n    );\n  }\n}\n